{"version":3,"file":"order.js","sources":["pages/order/order.vue","../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvb3JkZXIvb3JkZXIudnVl"],"sourcesContent":["<template>\n\t<view class=\"message-container\">\n\t  <!-- 顶部标题栏 -->\n\t  <view class=\"header\">\n\t\t<text class=\"title\">消息</text>\n\t  </view>\n\t  \n\t  <!-- 四个图标导航区域 -->\n\t  <view class=\"icon-nav\">\n\t\t<view class=\"icon-item\" @tap=\"selectMessageType(0)\">\n\t\t  <view class=\"icon-box\" :class=\"{ active: currentType === 0 }\">\n\t\t\t<image src=\"https://joinup.oss-cn-beijing.aliyuncs.com/images/message/team.png\" mode=\"aspectFit\"></image>\n\t\t  </view>\n\t\t  <text class=\"icon-text\" :class=\"{ active: currentType === 0 }\">组队</text>\n\t\t</view>\n\t\t\n\t\t<view class=\"icon-item\" @tap=\"selectMessageType(2)\">\n\t\t  <view class=\"icon-box\" :class=\"{ active: currentType === 2 }\">\n\t\t\t<image src=\"https://joinup.oss-cn-beijing.aliyuncs.com/images/message/boya.png\" mode=\"aspectFit\"></image>\n\t\t  </view>\n\t\t  <text class=\"icon-text\" :class=\"{ active: currentType === 2 }\">博雅</text>\n\t\t</view>\n\t\t\n\t\t<view class=\"icon-item\" @tap=\"selectMessageType(1)\">\n\t\t  <view class=\"icon-box\" :class=\"{ active: currentType === 1 }\">\n\t\t\t<image src=\"https://joinup.oss-cn-beijing.aliyuncs.com/images/message/course.png\" mode=\"aspectFit\"></image>\n\t\t  </view>\n\t\t  <text class=\"icon-text\" :class=\"{ active: currentType === 1 }\">课程</text>\n\t\t</view>\n\t\t\n\t\t<!-- 新增第四个图标 -->\n\t\t\n\t\t<!-- <view class=\"icon-item\" @tap=\"navigateTo('newFeature')\">\n\t\t  <view class=\"icon-box\">\n\t\t\t<image src=\"https://joinup.oss-cn-beijing.aliyuncs.com/images/message/plus.png\" mode=\"aspectFit\"></image>\n\t\t  </view>\n\t\t  <text class=\"icon-text\">+++</text>\n\t\t</view> -->\n\t\t\n\t  </view>\n\t  \n\t  <!-- 选择消息分类的Tab -->\n\t  <view class=\"message-tabs\" v-if=\"hasSelectedType\">\n\t\t<view \n\t\t  class=\"tab-item\" \n\t\t  :class=\"{ active: readStatus === null }\" \n\t\t  @tap=\"switchReadStatus(null)\"\n\t\t>\n\t\t  全部\n\t\t</view>\n\t\t<view \n\t\t  class=\"tab-item\" \n\t\t  :class=\"{ active: readStatus === false }\" \n\t\t  @tap=\"switchReadStatus(false)\"\n\t\t>\n\t\t  未读\n\t\t</view>\n\t\t<view \n\t\t  class=\"tab-item\" \n\t\t  :class=\"{ active: readStatus === true }\" \n\t\t  @tap=\"switchReadStatus(true)\"\n\t\t>\n\t\t  已读\n\t\t</view>\n\t  </view>\n\t  \n\t  <!-- 消息列表 -->\n\t  <scroll-view \n\t\tscroll-y \n\t\tclass=\"message-list\" \n\t\t:class=\"{'with-tabs': hasSelectedType}\"\n\t\t@scrolltolower=\"loadMore\"\n\t\trefresher-enabled\n\t\t:refresher-triggered=\"isRefreshing\"\n\t\t@refresherrefresh=\"onRefresh\">\n\t\t\n\t\t<view v-if=\"!hasSelectedType\" class=\"select-type-tips\">\n\t\t  <text>请选择消息类型</text>\n\t\t</view>\n\t\t\n\t\t<block v-else>\n\t\t  <view v-for=\"(item, index) in messageList\" :key=\"index\" class=\"message-item\">\n\t\t\t<view class=\"message-header\">\n\t\t\t  <view class=\"message-info\">\n\t\t\t\t<text class=\"message-time\">{{formatTime(item.createTime)}}</text>\n\t\t\t  </view>\n\t\t\t  <text class=\"message-read-status\" v-if=\"item.read\">已读</text>\n\t\t\t  <text class=\"message-read-status unread\" v-else>未读</text>\n\t\t\t</view>\n\t\t\t\n\t\t\t<view class=\"message-content\">\n\t\t\t  <text class=\"message-title\">{{item.title}}</text>\n\t\t\t  <text class=\"message-text\">{{item.content}}</text>\n\t\t\t</view>\n\t\t\t\n\t\t\t<view class=\"message-actions\">\n\t\t\t  <button class=\"action-btn confirm\" @tap=\"confirmMessage(item.id, index)\" :disabled=\"item.read\">\n\t\t\t\t{{ item.read ? '已确认' : '确认收到' }}\n\t\t\t  </button>\n\t\t\t  <button class=\"action-btn delete\" @tap=\"handleDeleteMessage(item.id, item.read, index)\">删除</button>\n\t\t\t</view>\n\t\t  </view>\n\t\t  \n\t\t  <view v-if=\"messageList.length === 0\" class=\"empty-tips\">\n\t\t\t<text>暂无{{getReadStatusText()}}{{getTypeText(currentType)}}消息</text>\n\t\t  </view>\n\t\t  \n\t\t  <!-- 加载更多提示 -->\n\t\t  <view class=\"loading-more\" v-if=\"isLoading\">\n\t\t\t<text>加载中...</text>\n\t\t  </view>\n\t\t</block>\n\t  </scroll-view>\n\t</view>\n  </template>\n  \n  <script>\n  import { ref, reactive } from 'vue'\n  import { getUserInfo, login, modifyUserInfo, getMyMessage, markMessageRead, deleteMessage } from \"../../api/api\"\n  \n  // 跳转详情页\n  const goDetail = (item) => {\n\tif (!item || !item.id) {\n\t  console.error('无效的 item 对象', item)\n\t  return\n\t}\n\tuni.navigateTo({\n\t  url: `/pages/detail/detail?item=${encodeURIComponent(JSON.stringify(item))}`  // 使用 encodeURIComponent 进行编码\n\t})\n  }\n  \n  export default {\n\tdata() {\n\t  return {\n\t\tisRefreshing: false,\n\t\tisLoading: false,\n\t\tcurrentType: null, // 使用null表示未选择类型\n\t\treadStatus: null,  // null: 全部, false: 未读, true: 已读\n\t\tcurrentPage: 1,\n\t\tpageSize: 10,\n\t\ttotalPages: 0,\n\t\thasSelectedType: false, // 标记是否已选择消息类型\n\t\t\n\t\t// 消息列表\n\t\tmessageList: [],\n\t\t\n\t\t// 图标页面链接\n\t\tpageLinks: {\n\t\t  team: '/pages/team/team',\n\t\t  boya: '/pages/boya/boya',\n\t\t  checkin: '/pages/checkin/checkin',\n\t\t  newFeature: '/pages/team/team' \n\t\t}\n\t  };\n\t},\n\tmethods: {\n\t  // 导航到对应页面\n\t  navigateTo(type) {\n\t\tconst url = this.pageLinks[type] || '/pages/index/index';\n\t\tuni.navigateTo({\n\t\t  url: url\n\t\t});\n\t  },\n\t  \n\t  // 获取消息类型对应的文本\n\t  getTypeText(type) {\n\t\tconst typeMap = {\n\t\t  0: '组队',\n\t\t  1: '课程',\n\t\t  2: '博雅'\n\t\t};\n\t\treturn typeMap[type] || '';\n\t  },\n\t  \n\t  // 获取阅读状态对应的文本\n\t  getReadStatusText() {\n\t\tif (this.readStatus === true) return '已读';\n\t\tif (this.readStatus === false) return '未读';\n\t\treturn '';\n\t  },\n\t  \n\t  // 选择消息类型\n\t  selectMessageType(type) {\n\t\tif (type === null || type === undefined) {\n\t\t  return;\n\t\t}\n\t\t\n\t\tthis.currentType = type;\n\t\tthis.hasSelectedType = true;\n\t\tthis.readStatus = null; // 默认显示全部消息\n\t\tthis.fetchMessages();\n\t  },\n\t  \n\t  // 切换阅读状态\n\t  switchReadStatus(status) {\n\t\tif (this.readStatus === status) return; // 已经是当前状态，不重复加载\n\t\t\n\t\tthis.readStatus = status;\n\t\tthis.fetchMessages();\n\t  },\n\t  \n\t  // 获取指定类型和阅读状态的消息\n\t  fetchMessages() {\n\t\tthis.isLoading = true;\n\t\tthis.currentPage = 1;\n\t\tthis.messageList = []; // 清空之前的消息列表\n\t\t\n\t\t// 构建请求参数\n\t\tconst params = {\n\t\t  pageSize: this.pageSize,\n\t\t  pageNumber: this.currentPage,\n\t\t  type: this.currentType\n\t\t};\n\t\t\n\t\t// 如果指定了阅读状态（全部/未读/已读）\n\t\tif (this.readStatus !== null) {\n\t\t  params.read = this.readStatus;\n\t\t}\n\t\t\n\t\tgetMyMessage(params).then(res => {\n\t\t\t//console.log(res);\n\t\t  if (res) {\n\t\t\tthis.messageList = res.list || [];\n\t\t\tthis.totalPages = res.pages || 0;\n\t\t  } else {\n\t\t\tthis.messageList = []; // 确保在出错时也清空消息列表\n\t\t\tuni.showToast({\n\t\t\t  title: res.msg || '获取消息失败',\n\t\t\t  icon: 'none'\n\t\t\t});\n\t\t  }\n\t\t  this.isLoading = false;\n\t\t  if (this.isRefreshing) {\n\t\t\tthis.isRefreshing = false;\n\t\t  }\n\t\t}).catch(err => {\n\t\t  console.error(\"获取消息失败\", err);\n\t\t  this.messageList = []; // 确保在出错时也清空消息列表\n\t\t  this.isLoading = false;\n\t\t  if (this.isRefreshing) {\n\t\t\tthis.isRefreshing = false;\n\t\t  }\n\t\t  uni.showToast({\n\t\t\ttitle: '获取消息失败',\n\t\t\ticon: 'none'\n\t\t  });\n\t\t});\n\t  },\n\t  \n\t  // 下拉刷新\n\t  onRefresh() {\n\t\tthis.isRefreshing = true;\n\t\t// 只有已经选择了消息类型才刷新\n\t\tif (this.hasSelectedType) {\n\t\t  this.fetchMessages();\n\t\t} else {\n\t\t  this.isRefreshing = false;\n\t\t}\n\t  },\n\t  \n\t  // 加载更多\n\t  loadMore() {\n\t\tif (this.isLoading || this.currentPage >= this.totalPages || !this.hasSelectedType) return;\n\t\t\n\t\tthis.isLoading = true;\n\t\tthis.currentPage++;\n\t\t\n\t\t// 构建请求参数\n\t\tconst params = {\n\t\t  pageSize: this.pageSize,\n\t\t  pageNumber: this.currentPage,\n\t\t  type: this.currentType\n\t\t};\n\t\t\n\t\t// 如果指定了阅读状态（全部/未读/已读）\n\t\tif (this.readStatus !== null) {\n\t\t  params.read = this.readStatus;\n\t\t}\n\t\t\n\t\tgetMyMessage(params).then(res => {\n\t\t  if (res) {\n\t\t\tconst newList = res.data.list || [];\n\t\t\tthis.messageList = [...this.messageList, ...newList];\n\t\t  }\n\t\t  this.isLoading = false;\n\t\t}).catch(err => {\n\t\t  console.error(\"加载更多消息失败\", err);\n\t\t  this.isLoading = false;\n\t\t  uni.showToast({\n\t\t\ttitle: '加载更多失败',\n\t\t\ticon: 'none'\n\t\t  });\n\t\t});\n\t  },\n\t  \n\t  // 确认收到消息\n\t  confirmMessage(id, index) {\n\t\t// 如果已读，不执行操作\n\t\tif (this.messageList[index] && this.messageList[index].read) {\n\t\t  return;\n\t\t}\n\t\t\n\t\tuni.showModal({\n\t\t  title: '确认',\n\t\t  content: '是否确认收到该消息？',\n\t\t  success: (res) => {\n\t\t\tif (res.confirm) {\n\t\t\t  // 显示加载中\n\t\t\t  uni.showLoading({\n\t\t\t\ttitle: '确认中...'\n\t\t\t  });\n\t\t\t  \n\t\t\t  // 调用标记消息为已读的API\n\t\t\t  markMessageRead(id).then(res => {\n\t\t\t\tuni.hideLoading();\n\t\t\t\t\n\t\t\t\tif (res.code === 1) {\n\t\t\t\t  // 成功\n\t\t\t\t  uni.showToast({\n\t\t\t\t\ttitle: '确认成功',\n\t\t\t\t\ticon: 'success'\n\t\t\t\t  });\n\t\t\t\t  \n\t\t\t\t  // 如果当前是显示未读消息，则从列表中移除此消息\n\t\t\t\t  if (this.readStatus === false) {\n\t\t\t\t\tthis.messageList.splice(index, 1);\n\t\t\t\t  } else {\n\t\t\t\t\t// 否则更新本地消息状态\n\t\t\t\t\tif (this.messageList[index]) {\n\t\t\t\t\t  this.messageList[index].read = true;\n\t\t\t\t\t  // 使用Vue的响应式更新，确保视图更新\n\t\t\t\t\t  this.$set(this.messageList, index, {...this.messageList[index]});\n\t\t\t\t\t}\n\t\t\t\t  }\n\t\t\t\t} else {\n\t\t\t\t  // 失败\n\t\t\t\t  uni.showToast({\n\t\t\t\t\ttitle: res.msg || '确认失败',\n\t\t\t\t\ticon: 'none'\n\t\t\t\t  });\n\t\t\t\t}\n\t\t\t  }).catch(err => {\n\t\t\t\tuni.hideLoading();\n\t\t\t\tconsole.error(\"确认消息失败\", err);\n\t\t\t\tuni.showToast({\n\t\t\t\t  title: '确认失败，请稍后重试',\n\t\t\t\t  icon: 'none'\n\t\t\t\t});\n\t\t\t  });\n\t\t\t}\n\t\t  }\n\t\t});\n\t  },\n\t  \n\t  // 处理删除消息逻辑\n\t  handleDeleteMessage(id, isRead, index) {\n\t\t// 如果消息未读，显示特殊提示\n\t\tif (!isRead) {\n\t\t  uni.showModal({\n\t\t\ttitle: '提示',\n\t\t\tcontent: '该消息未读，确定要删除吗？',\n\t\t\tsuccess: (res) => {\n\t\t\t  if (res.confirm) {\n\t\t\t\tthis.performDeleteMessage(id, index);\n\t\t\t  }\n\t\t\t}\n\t\t  });\n\t\t} else {\n\t\t  // 已读消息直接进入常规删除流程\n\t\t  uni.showModal({\n\t\t\ttitle: '提示',\n\t\t\tcontent: '确定要删除这条消息吗？',\n\t\t\tsuccess: (res) => {\n\t\t\t  if (res.confirm) {\n\t\t\t\tthis.performDeleteMessage(id, index);\n\t\t\t  }\n\t\t\t}\n\t\t  });\n\t\t}\n\t  },\n\t  \n\t  // 执行删除消息API调用\n\t  performDeleteMessage(id, index) {\n\t\t// 显示加载中\n\t\tuni.showLoading({\n\t\t  title: '删除中...'\n\t\t});\n\t\t\n\t\t// 调用删除消息API\n\t\tdeleteMessage(id).then(res => {\n\t\t  uni.hideLoading();\n\t\t  \n\t\t  if (res.code === 1) {\n\t\t\t// 成功\n\t\t\tuni.showToast({\n\t\t\t  title: '删除成功',\n\t\t\t  icon: 'success'\n\t\t\t});\n\t\t\t\n\t\t\t// 从列表中移除该消息\n\t\t\tthis.messageList.splice(index, 1);\n\t\t  } else {\n\t\t\t// 失败\n\t\t\tuni.showToast({\n\t\t\t  title: res.msg || '删除失败',\n\t\t\t  icon: 'none'\n\t\t\t});\n\t\t  }\n\t\t}).catch(err => {\n\t\t  uni.hideLoading();\n\t\t  console.error(\"删除消息失败\", err);\n\t\t  uni.showToast({\n\t\t\ttitle: '删除失败，请稍后重试',\n\t\t\ticon: 'none'\n\t\t  });\n\t\t});\n\t  },\n\t  \n\t  // 格式化时间\n\t  formatTime(timeStr) {\n\t\tif (!timeStr) return '';\n\t\tconst date = new Date(timeStr);\n\t\treturn `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-${date.getDate().toString().padStart(2, '0')} ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;\n\t  }\n\t}\n  };\n  </script>\n  \n  <style lang=\"scss\">\n  .message-container {\n\tdisplay: flex;\n\tflex-direction: column;\n\theight: 100vh;\n\tbackground-color: #f8f8f8;\n  }\n  \n  /* 顶部标题 */\n  .header {\n\tpadding: 44rpx 30rpx 20rpx;\n\tbackground-color: #fff;\n\tdisplay: flex;\n\tjustify-content: center;\n\t\n\t.title {\n\t  font-size: 40rpx;\n\t  font-weight: bold;\n\t  color: #333;\n\t}\n  }\n  \n  /* 四个图标导航 */\n  .icon-nav {\n\tdisplay: flex;\n\tjustify-content: space-around;\n\talign-items: flex-start;\n\tpadding: 30rpx 20rpx;\n\tbackground-color: #fff;\n\tmargin-bottom: 0; // 减少底部间距，因为Tab会紧接着\n\tflex-wrap: wrap;\n\t\n\t.icon-item {\n\t  display: flex;\n\t  flex-direction: column;\n\t  align-items: center;\n\t  width: 25%;\n\t  box-sizing: border-box;\n\t  padding: 0 10rpx;\n\t  margin-bottom: 20rpx;\n\t  \n\t  .icon-box {\n\t\twidth: 120rpx;\n\t\theight: 120rpx;\n\t\tborder-radius: 30rpx;\n\t\tbackground-color: #f5f5f5;\n\t\tdisplay: flex;\n\t\talign-items: center;\n\t\tjustify-content: center;\n\t\tmargin-bottom: 16rpx;\n\t\toverflow: hidden;\n\t\ttransition: background-color 0.3s;\n\t\t\n\t\t&.active {\n\t\t  background-color: #e6f7ff;\n\t\t  border: 2px solid #1890ff;\n\t\t}\n\t\t\n\t\timage {\n\t\t  width: 60rpx;\n\t\t  height: 60rpx;\n\t\t}\n\t  }\n\t  \n\t  .icon-text {\n\t\tfont-size: 26rpx;\n\t\tcolor: #333;\n\t\t\n\t\t&.active {\n\t\t  color: #1890ff;\n\t\t  font-weight: bold;\n\t\t}\n\t  }\n\t}\n  }\n  \n  /* 消息Tab栏 */\n  .message-tabs {\n\tdisplay: flex;\n\tbackground-color: #fff;\n\tborder-bottom: 1px solid #f0f0f0;\n\tmargin-bottom: 20rpx;\n\t\n\t.tab-item {\n\t  flex: 1;\n\t  text-align: center;\n\t  padding: 24rpx 0;\n\t  font-size: 28rpx;\n\t  color: #666;\n\t  position: relative;\n\t  \n\t  &.active {\n\t\tcolor: #1890ff;\n\t\tfont-weight: 500;\n\t\t\n\t\t&:after {\n\t\t  content: '';\n\t\t  position: absolute;\n\t\t  bottom: 0;\n\t\t  left: 50%;\n\t\t  transform: translateX(-50%);\n\t\t  width: 40rpx;\n\t\t  height: 4rpx;\n\t\t  background-color: #1890ff;\n\t\t  border-radius: 2rpx;\n\t\t}\n\t  }\n\t}\n  }\n  \n  /* 消息列表 */\n  .message-list {\n\tflex: 1;\n\tbackground-color: #fff;\n\t\n\t&.with-tabs {\n\t  margin-top: 0;\n\t}\n  }\n  \n  /* 选择类型提示 */\n  .select-type-tips {\n\tdisplay: flex;\n\tflex-direction: column;\n\talign-items: center;\n\tjustify-content: center;\n\tpadding: 100rpx 0;\n\t\n\timage {\n\t  width: 200rpx;\n\t  height: 200rpx;\n\t  margin-bottom: 20rpx;\n\t}\n\t\n\ttext {\n\t  font-size: 32rpx;\n\t  color: #666;\n\t  font-weight: 500;\n\t}\n  }\n  \n  /* 消息项样式 */\n  .message-item {\n\tpadding: 30rpx;\n\tborder-bottom: 1px solid #f0f0f0;\n\tbackground-color: #fff;\n  }\n  \n  .message-header {\n\tdisplay: flex;\n\tjustify-content: space-between;\n\talign-items: center;\n\tmargin-bottom: 16rpx;\n  }\n  \n  .message-info {\n\tdisplay: flex;\n\tflex-direction: column;\n  }\n  \n  .message-sender {\n\tfont-size: 28rpx;\n\tcolor: #666;\n\tmargin-bottom: 8rpx;\n  }\n  \n  .message-time {\n\tfont-size: 24rpx;\n\tcolor: #999;\n  }\n  \n  .message-read-status {\n\tfont-size: 24rpx;\n\tcolor: #999;\n\t\n\t&.unread {\n\t  color: #ff4d4f;\n\t}\n  }\n  \n  .message-content {\n\tmargin-bottom: 24rpx;\n  }\n  \n  .message-title {\n\tfont-size: 32rpx;\n\tfont-weight: 500;\n\tcolor: #333;\n\tmargin-bottom: 12rpx;\n\tdisplay: block;\n  }\n  \n  .message-text {\n\tfont-size: 28rpx;\n\tcolor: #666;\n\tline-height: 1.5;\n\tdisplay: block;\n  }\n  \n  .message-actions {\n\tdisplay: flex;\n\tjustify-content: flex-end;\n\tgap: 20rpx;\n  }\n  \n  .action-btn {\n\tmin-width: 160rpx;\n\tpadding: 10rpx 20rpx;\n\tborder-radius: 8rpx;\n\tfont-size: 26rpx;\n\ttext-align: center;\n\tline-height: 1.5;\n\t\n\t&.confirm {\n\t  background-color: #1890ff;\n\t  color: #fff;\n\t  \n\t  &[disabled] {\n\t\tbackground-color: #bae7ff;\n\t\tcolor: #fff;\n\t\topacity: 0.7;\n\t  }\n\t}\n\t\n\t&.delete {\n\t  background-color: #ff4d4f;\n\t  color: #fff;\n\t}\n  }\n  \n  /* 空状态提示 */\n  .empty-tips {\n\tdisplay: flex;\n\tflex-direction: column;\n\talign-items: center;\n\tjustify-content: center;\n\tpadding: 100rpx 0;\n\t\n\timage {\n\t  width: 200rpx;\n\t  height: 200rpx;\n\t  margin-bottom: 20rpx;\n\t}\n\t\n\ttext {\n\t  font-size: 28rpx;\n\t  color: #999;\n\t}\n  }\n  \n  /* 加载提示 */\n  .loading-more {\n\ttext-align: center;\n\tpadding: 30rpx 0;\n\t\n\ttext {\n\t  font-size: 24rpx;\n\t  color: #999;\n\t}\n  }\n  </style>","import MiniProgramPage from 'D:/uniapp/myJoinup/joinup/pages/order/order.vue'\nwx.createPage(MiniProgramPage)"],"nam